    ('july-13', 'july-13-draft-dialogue', 23, 'Use It', 'dialogue', '{"id":"july-13-draft-dialogue","format":"dialogue","type":"dialogue","section":"Use It","topic":"time","isOriginal":false,"hint":"Focus on the time meaning. Look for the sentence that expresses “週の初めは長く感じます。”.","hintJa":"「週の初めは長く感じます。」を表す英文と、timeの形に注目しましょう。","explanation":"“It feels long at the beginning of the week.” answers the previous speaker directly and keeps the conversation coherent.","explanationJa":"「It feels long at the beginning of the week.」は直前の発言に直接答え、会話の流れが自然につながります。","prompt":"Choose the most natural next line.","promptJa":"会話の次の一文を選んでください。","context":"A: How does the week feel on Monday?\nB: ...","contextJa":"A：「月曜日は一週間がどう感じますか？」\nB：…","choices":[{"id":"a","en":"It feels long at the beginning of the week.","jp":"週の初めは長く感じます。"},{"id":"b","en":"Will you be there this time?","jp":"今回はそこにいますか？"},{"id":"c","en":"No one usually calls me at this time.","jp":"この時間には普段誰も電話しません。"},{"id":"d","en":"That’s unusual.","jp":"それは珍しいですね。"}],"correct":"a"}'::jsonb, false, 1),
