    ('july-22', 'july-22-draft-listen-choice-1', 12, 'Listen', 'listenChoice', '{"id":"july-22-draft-listen-choice-1","format":"listenChoice","type":"listenChoice","section":"Listen","topic":"availability","isOriginal":false,"hint":"Focus on the availability meaning. Look for the sentence that expresses “8月4日午前10時はご都合いかがですか？”.","hintJa":"「8月4日午前10時はご都合いかがですか？」を表す英文と、availabilityの形に注目しましょう。","explanation":"The sentence in the audio is “Would you be available on August 4th at 10 a.m.?”. Listen through to the end before choosing.","explanationJa":"音声の英文は「Would you be available on August 4th at 10 a.m.?」です。最後まで聞いてから選びましょう。","prompt":"Listen and choose the sentence.","promptJa":"音声を聞いて英文を選んでください。","audioText":"Would you be available on August 4th at 10 a.m.?","choices":[{"id":"a","en":"Would you be available on August 4th at 10 a.m.?","jp":"8月4日午前10時はご都合いかがですか？"},{"id":"b","en":"Are you guys ready?","jp":"皆さん、準備はできましたか？"},{"id":"c","en":"Neither is okay.","jp":"どちらも駄目です。"},{"id":"d","en":"That’s right. I don’t like it.","jp":"その通りです。好きではありません。"}],"correct":"a"}'::jsonb, false, 1),
    ('july-22', 'july-22-draft-listen-choice-2', 13, 'Listen', 'listenChoice', '{"id":"july-22-draft-listen-choice-2","format":"listenChoice","type":"listenChoice","section":"Listen","topic":"either","isOriginal":false,"hint":"Focus on the either meaning. Look for the sentence that expresses “どちらでも大丈夫です。”.","hintJa":"「どちらでも大丈夫です。」を表す英文と、eitherの形に注目しましょう。","explanation":"The sentence in the audio is “Either is fine.”. Listen through to the end before choosing.","explanationJa":"音声の英文は「Either is fine.」です。最後まで聞いてから選びましょう。","prompt":"Listen and choose the sentence.","promptJa":"音声を聞いて英文を選んでください。","audioText":"Either is fine.","choices":[{"id":"a","en":"Either is fine.","jp":"どちらでも大丈夫です。"},{"id":"b","en":"Neither is okay.","jp":"どちらも駄目です。"},{"id":"c","en":"No, I don’t. I don’t like it.","jp":"いいえ、好きではありません。"},{"id":"d","en":"Is the meeting room available?","jp":"会議室は利用できますか？"}],"correct":"a"}'::jsonb, false, 1),
